def gerar_chave_comparacao_descricao(descricao):
    if not descricao:
        return ''

    # Faz normalização unicode, incluindo decomposição de letras acentuadas ("é", p.ex., torna-se "e´").
    descricao = unicodedata.normalize('NFKD', descricao)

    # Remove acentuação
    descricao = ''.join(
        c for c in unicodedata.normalize('NFD', descricao)
        if unicodedata.category(c) != 'Mn'
    )

    # Converte para minúsculas
    descricao = descricao.lower()

    # Remove pontuação e caracteres especiais
    descricao = re.sub(r'[^a-zA-Z0-9 ]', '', descricao)

    # Corrige espaços repetidos
    descricao = re.sub(r'\s+', ' ', descricao).strip()

    return descricao


def combinar_disciplinas(bibliografia_1, bibliografia_2) -> list:
    lista_1 = bibliografia_1.disciplinas.split('|') if bibliografia_1.disciplinas.strip() else []
    lista_2 = bibliografia_2.disciplinas.split('|') if bibliografia_2.disciplinas.strip() else []
    return list(set(lista_1 + lista_2))


def popular_chave_comparacao_descricao(apps, schema_editor):
    BibliografiaPAFC = apps.get_model('pafc', 'BibliografiaPAFC')

    def chave_da_cache(bibliografia):
        return f'{bibliografia.pafc_id}_{bibliografia.tipo_bibliografia}_{bibliografia.chave_comparacao_descricao}'

    cache_bibliografias = {}

    ids_registros_a_remover = []

    logger.info('Preenchendo chave_comparacao_descricao de BibliografiaPAFC...')
    for bibliografia in tqdm(BibliografiaPAFC.objects.order_by('id').all()):
        bibliografia.chave_comparacao_descricao = gerar_chave_comparacao_descricao(bibliografia.descricao)
        bibliografia_existente = cache_bibliografias.get(chave_da_cache(bibliografia))

        if bibliografia_existente:
            # combinando disciplinas de ambas
            bibliografia_existente.disciplinas = '|'.join(sorted(combinar_disciplinas(bibliografia_existente, bibliografia)))

            ids_registros_a_remover.append(bibliografia.id)
        else:
            cache_bibliografias[chave_da_cache(bibliografia)] = bibliografia

    logger.info(f'Atualizando {len(cache_bibliografias)} registros...')
    BibliografiaPAFC.objects.bulk_update(list(cache_bibliografias.values()), ['chave_comparacao_descricao', 'disciplinas'])

    if ids_registros_a_remover:
        logger.info(f'Removendo {len(ids_registros_a_remover)} registros duplicados...')
        BibliografiaPAFC.objects.filter(pk__in=ids_registros_a_remover).delete()
    else:
        logger.info('Nenhum registro duplicado para remover.')


